solucao.solucao.js:
export function doisNumeros(numeros, alvo) {
  const vistos = new Map();
  for (let i = 0; i < numeros.length; i++) {
    const falta = alvo - numeros[i];
    if (vistos.has(falta)) return [vistos.get(falta), i];
    vistos.set(numeros[i], i);
  }
  return [];
}

