import { test } from "node:test";
import assert from "node:assert/strict";
import { totalDoCarrinho } from "./carrinho.js";

test("o desconto pode tirar o frete grátis", () => {
  assert.equal(totalDoCarrinho([{ preco: 21000, quantidade: 1 }], "DEZ"), 18900 + 1500);
});

test("cupom desconhecido não dá desconto", () => {
  assert.equal(totalDoCarrinho([{ preco: 999, quantidade: 3 }], "MIL"), 2997 + 1500);
});

test("arredonda o desconto para baixo", () => {
  assert.equal(totalDoCarrinho([{ preco: 1005, quantidade: 1 }], "DEZ"), 1005 - 100 + 1500);
});
